import{_ as o,C as s,o as i,c as l,aj as e,E as d}from"./framework.js";const m=JSON.parse('{"title":"HTML 片段 | Cms / Content | Documentation","description":"HTML 片段（HtmlBlock）用于在后台集中维护一段 HTML 内容，在多个 Page、Layout、View 中复用。前台渲染时按当前站点语言输出对应版本，避免同一段页脚、广告条在多处复制粘贴。","frontmatter":{"title":"HTML 片段 | Cms / Content | Documentation","description":"HTML 片段（HtmlBlock）用于在后台集中维护一段 HTML 内容，在多个 Page、Layout、View 中复用。前台渲染时按当前站点语言输出对应版本，避免同一段页脚、广告条在多处复制粘贴。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/content/html-blocks.html"}]]},"headers":[],"relativePath":"zh/cms/content/html-blocks.md","filePath":"cms/content/html-blocks.md","lastUpdated":1780283766000}'),r={name:"zh/cms/content/html-blocks.md"};function n(h,t,c,k,p,g){const a=s("DocImage");return i(),l("div",null,[t[0]||(t[0]=e('<h1 id="html-片段" tabindex="-1">HTML 片段 <a class="header-anchor" href="#html-片段" aria-label="Permalink to &quot;HTML 片段&quot;">​</a></h1><blockquote><p>菜单：<strong>内容 → HTML 片段</strong><br> 深链：<code>/_Admin/content/htmlblocks?SiteId={站点GUID}</code><br> 编辑：<code>/_Admin/content/htmlBlock/edit?SiteId=...&amp;id={片段Id}</code>（新建无 <code>id</code>）</p></blockquote><p><strong>HTML 片段</strong>（HtmlBlock）用于在后台集中维护一段 <strong>HTML 内容</strong>，在多个 Page、Layout、View 中复用。前台渲染时按当前站点语言输出对应版本，避免同一段页脚、广告条在多处复制粘贴。</p><div class="tip custom-block"><p class="custom-block-title">与 View、标签的区别</p><table tabindex="0"><thead><tr><th></th><th>HTML 片段</th><th><a href="/kb-docs/zh/templateEngine/view/">View</a></th><th><a href="./labels.html">标签</a></th></tr></thead><tbody><tr><td>后台菜单</td><td>内容 → HTML 片段</td><td>开发 → View</td><td>内容 → 标签</td></tr><tr><td>内容形态</td><td>富文本/HTML 块</td><td>模板片段（常含绑定）</td><td>短文案字符串</td></tr><tr><td>模板引用</td><td><code>&lt;htmlblock id=&quot;...&quot;&gt;</code></td><td><code>&lt;view id=&quot;...&quot;&gt;</code></td><td><code>k.label()</code></td></tr></tbody></table></div><div class="tip custom-block"><p class="custom-block-title">前置：多语言（可选）</p><p>与 <a href="./labels.html">标签</a> 相同：若站点启用多种语言，编辑页会为每种语言提供 <strong>内容</strong> 字段；须在 <strong>站点设置 → 基础设置</strong> 中先配置语言。单语言站点只显示一个 <strong>内容</strong> 输入区。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>进入站点后台（地址栏带 <code>SiteId</code>）。</li><li>左侧 <strong>内容 → HTML 片段</strong>。</li></ol>',7)),d(a,{src:"/cms/content/html-blocks-list.png",alt:"HTML 片段列表",width:"1120"}),t[1]||(t[1]=e('<h2 id="列表页" tabindex="-1">列表页 <a class="header-anchor" href="#列表页" aria-label="Permalink to &quot;列表页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>片段标识，与模板中 <code>id</code> 一致；建议英文，如 <code>footer_links</code>、<code>promo_banner</code></td></tr><tr><td>引用</td><td>被哪些 Page / Layout / View 等资源引用（可点击查看）</td></tr><tr><td>最后修改</td><td>更新时间</td></tr><tr><td><strong>编辑</strong></td><td>进入编辑页</td></tr><tr><td><strong>版本</strong></td><td>版本历史（站点日志权限允许时）</td></tr></tbody></table><p>工具栏 <strong>新建</strong> 进入编辑页（无 <code>id</code>）。勾选多行可 <strong>批量删除</strong>（权限 <code>htmlBlock</code> · <code>delete</code>）。</p><h2 id="编辑页" tabindex="-1">编辑页 <a class="header-anchor" href="#编辑页" aria-label="Permalink to &quot;编辑页&quot;">​</a></h2><p>全屏表单 + 底部 <strong>保存</strong> / <strong>取消</strong>。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td><strong>新建</strong>时填写，须唯一、1～50 字符、符合资源命名规则；<strong>保存后不可改名</strong>（编辑时只读展示）</td></tr><tr><td>内容 · <code>{语言}</code></td><td>每种已启用语言一行，使用 <strong>富文本/HTML 编辑器</strong>（KEditor）维护该语言下的 HTML</td></tr><tr><td>多语言选择器</td><td>右上角切换当前编辑侧重（各语言字段仍按语言列出）</td></tr></tbody></table><p>离开页面前若有未保存修改，会提示确认。</p>',7)),d(a,{src:"/cms/content/html-blocks-edit.png",alt:"编辑 HTML 片段",width:"1120"}),t[2]||(t[2]=e('<h2 id="在模板中引用" tabindex="-1">在模板中引用 <a class="header-anchor" href="#在模板中引用" aria-label="Permalink to &quot;在模板中引用&quot;">​</a></h2><p>片段 <strong>名称</strong> 与下列写法中的 <code>id</code> / 绑定值一致（大小写以站点内资源名为准）：</p><h3 id="标签形式-常用" tabindex="-1">标签形式（常用） <a class="header-anchor" href="#标签形式-常用" aria-label="Permalink to &quot;标签形式（常用）&quot;">​</a></h3><p>在 Page、Layout 或 View 的 HTML 中：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">htmlblock</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;footer_links&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">htmlblock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="绑定属性" tabindex="-1">绑定属性 <a class="header-anchor" href="#绑定属性" aria-label="Permalink to &quot;绑定属性&quot;">​</a></h3><p>也可使用渲染绑定（与引擎 <code>k-htmlblock</code> / <code>v-htmlblock</code> 对应）：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> k-htmlblock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;footer_links&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>渲染时输出该片段在当前请求语言下的 HTML；找不到片段时行为以引擎为准（开发环境可对照资源名排查）。</p><div class="tip custom-block"><p class="custom-block-title">与 Layout 占位</p><p>片段常放在 Layout 的 <code>&lt;placeholder&gt;</code> 内，或与 <code>&lt;view&gt;</code> 并列使用，用于全站统一的页脚、侧栏公告等。Page 结构见 <a href="/kb-docs/zh/templateEngine/page/">模板引擎 · Page</a>。</p></div><h2 id="其它入口" tabindex="-1">其它入口 <a class="header-anchor" href="#其它入口" aria-label="Permalink to &quot;其它入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td><a href="/kb-docs/zh/cms/site/pages-inline-edit.html">在线编辑</a></td><td>若站点开启「编辑 HTML 片段」，可在预览页选中已绑定的片段块，右键/工具条进入编辑（保存后刷新预览）</td></tr><tr><td>页面树</td><td><strong>页面</strong> 列表的 <strong>页面树</strong> 视图中，可将选中节点 <strong>转换成 HTML 代码块</strong>（新建或合并到已有片段），便于把重复 DOM 抽成片段</td></tr><tr><td>开发 · 代码搜索</td><td>可跳转到片段编辑页</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./">内容模块概述</a></td><td>内容分组菜单</td></tr><tr><td><a href="./labels.html">标签</a></td><td>多语言短文案</td></tr><tr><td><a href="/kb-docs/zh/templateEngine/view/">View</a></td><td>可复用视图片段</td></tr><tr><td><a href="/kb-docs/zh/cms/site/pages-inline-edit.html">在线编辑</a></td><td>前台可视化改片段</td></tr><tr><td><a href="/kb-docs/zh/api/utils/inlineHtml.html">k.utils.inlineHtml</a></td><td>将外部资源内联进 HTML 导出（与 HtmlBlock 管理无关）</td></tr></tbody></table>',14))])}const u=o(r,[["render",n]]);export{m as __pageData,u as default};
